{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C54"],
      "claim": "Urapidil absolute oral bioavailability was 72% (95% CI 63–80%) relative to IV in healthy/normotensive subjects, well above the 20% threshold."
    },
    {
      "card_ids": ["C36"],
      "claim": "Bosentan absolute oral bioavailability was 50% after a 500 mg oral dose versus IV in healthy male subjects, supporting F ≥20%."
    },
    {
      "card_ids": ["C62"],
      "claim": "Acalabrutinib absolute oral bioavailability was 25.3% (geometric mean) after a 100 mg oral capsule versus IV in humans, still above the 20% threshold."
    }
  ],
  "confidence": "high",
  "contradictory_card_ids": [],
  "decision_summary": "All usable numeric absolute bioavailability evidence from high-transfer molecules supports F ≥20%, with values ranging from about 25% to 82%. Fed-state and provenance conflicts introduce minor uncertainty but do not overturn the positive direction.",
  "evidence_gaps": [
    "Molecule 3 includes a brigatinib record (C26) alongside GSK1322322 records; identity conflict, so C26 was discounted.",
    "Molecule 10 includes an abemaciclib record (C47) alongside acalabrutinib records; identity conflict, so C47 was discounted.",
    "Rigosertib fed-state absolute F was 13.9% (C01), below threshold, but fasting absolute F was 35% (C34); condition-dependent uncertainty remains."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C54", "C36", "C62"],
  "revision_action": "initial",
  "supportive_card_ids": ["C54", "C36", "C62"]
}

